"""Build the generated files of the phone web app in docs/.

Run from the repository root:

    python3 tools/build_web.py

It writes:

  docs/data.js     the trained model (models/model.json) and the measured
                   results (results/results.csv, ablation.csv, sweep.csv) as
                   a script that sets MLPR_DATA, so the page works from a
                   plain file or static host without fetching anything;
  docs/index.html  docs/app.html wrapped in a complete HTML document, for
                   GitHub Pages (only when docs/app.html exists). app.html
                   holds what goes in <head>, then the marker comment
                   <!-- body -->, then the body; a hosting service that adds
                   its own document skeleton can publish app.html as it is.
"""

from __future__ import annotations

import argparse
import csv
import json
import math
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
MODEL = ROOT / "models" / "model.json"
RESULTS = ROOT / "results"
MARKER = "<!-- body -->"

DATA_PREFIX = '(typeof self !== "undefined" ? self : globalThis).MLPR_DATA = '

INDEX_HEAD = (
    '<html lang="en"><head><meta charset="utf-8">'
    '<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">'
    "<style>:root{color-scheme:light;padding-top:env(safe-area-inset-top,0px);"
    "padding-bottom:env(safe-area-inset-bottom,0px)}"
    'body{margin:0;font:14px/1.4 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}'
    "img{max-width:100%}[hidden]{display:none!important}</style>"
)
INDEX_NOTE = "<!-- generated from docs/app.html by tools/build_web.py; edit app.html instead -->"

INT = re.compile(r"[-+]?\d+")
FLOAT = re.compile(r"[-+]?(\d+\.?\d*|\.\d+)([eE][-+]?\d+)?|[-+]?(nan|inf|infinity)", re.IGNORECASE)


def git_hash() -> str:
    try:
        out = subprocess.run(["git", "rev-parse", "--short", "HEAD"], cwd=ROOT, capture_output=True, text=True, check=True)
        return out.stdout.strip() or "unknown"
    except (OSError, subprocess.CalledProcessError):
        return "unknown"


def _number(text: str, as_int: bool):
    if text == "":
        return None
    if as_int:
        return int(text)
    value = float(text)
    return value if math.isfinite(value) else None  # JSON has no NaN or infinity


def read_csv(path: Path) -> list[dict]:
    """Rows of a CSV file; a column whose every value is a number becomes numbers (int if all are integers)."""
    with path.open(newline="") as f:
        rows = list(csv.DictReader(f))
    if not rows:
        return []
    for column in rows[0]:
        values = [r[column] for r in rows if r[column] != ""]
        if not values or not all(FLOAT.fullmatch(v) for v in values):
            continue
        as_int = all(INT.fullmatch(v) for v in values)
        for r in rows:
            r[column] = _number(r[column], as_int)
    return rows


def _rows(rows: list[dict]) -> str:
    return "[\n" + ",\n".join(json.dumps(r, separators=(",", ":"), allow_nan=False) for r in rows) + "\n]"


def write_data(docs: Path) -> Path:
    model = json.loads(MODEL.read_text())
    parts = [
        '"model":' + json.dumps(model, separators=(",", ":"), allow_nan=False),
        '"results":' + _rows(read_csv(RESULTS / "results.csv")),
        '"ablation":' + _rows(read_csv(RESULTS / "ablation.csv")),
        '"sweep":' + _rows(read_csv(RESULTS / "sweep.csv")),
        '"source":' + json.dumps(git_hash()),
    ]
    path = docs / "data.js"
    path.write_text(
        DATA_PREFIX + "{\n" + ",\n".join(parts) + "\n};\n"
        "// generated by tools/build_web.py from models/model.json and results/*.csv; do not edit\n"
    )
    return path


def write_index(docs: Path) -> Path | None:
    app = docs / "app.html"
    if not app.exists():
        return None
    text = app.read_text()
    if MARKER not in text:
        raise SystemExit(f"{app} has no {MARKER} marker: put the <head> part before it and the body after it")
    head, body = text.split(MARKER, 1)
    path = docs / "index.html"
    path.write_text(
        "<!doctype html>\n" + INDEX_NOTE + "\n" + INDEX_HEAD + "\n" + head.strip() + "\n</head><body>\n" + body.strip() + "\n</body></html>\n"
    )
    return path


def main(argv: list[str] | None = None) -> None:
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--docs", type=Path, default=ROOT / "docs", help="output directory (default: docs/)")
    args = parser.parse_args(argv)
    args.docs.mkdir(parents=True, exist_ok=True)
    for path in (write_data(args.docs), write_index(args.docs)):
        if path is not None:
            shown = path.relative_to(ROOT) if path.is_relative_to(ROOT) else path
            print(f"wrote {shown} ({path.stat().st_size / 1024:.0f} KB)")
    if not (args.docs / "app.html").exists():
        print("no docs/app.html yet: skipped docs/index.html", file=sys.stderr)


if __name__ == "__main__":
    main()
